function petOutfitFrame(stage,look=[]){
 const selected=petOutfitSelection(look),column=petHeadFrames.indexOf(selected.head),row=petBodyFrames.indexOf(selected.body)+(selected.eyewear?4:0),frame=row*5+column,[idle,smile]=petSceneFrames[stage][frame];
 return `<span class="pet-integrated-frame" data-outfit="${frame}" style="--pet-sheet:url('bogeumi-integrated-${stage}.webp');--pet-smile-sheet:url('bogeumi-smile-${stage}.webp');--pet-idle-size:${idle.size};--pet-smile-size:${smile.size};--pet-idle-position:${idle.position};--pet-smile-position:${smile.position};--pet-idle-clip:${idle.clip};--pet-smile-clip:${smile.clip}" aria-hidden="true"></span>`;
}
function petSprite(stage,extra=''){return `<div class="bogeumi-sprite pet-stage-sprite ${extra}" role="img" aria-label="${petStageNames[stage]} 캐릭터">${petOutfitFrame(stage)}</div>`;}
function petAvatar(stage,look='',color=''){
 const selected=petOutfitSelection(look),looks=Object.values(selected).filter(Boolean);
 return `<div class="pet-avatar pet-integrated-avatar ${color}" data-pet-stage="${stage}" role="img" aria-label="${petStageNames[stage]}${looks.length?' · '+looks.map(key=>petLookLabels[key]).join(', '):''}">${petOutfitFrame(stage,looks)}</div>`;
}

